L["Built-in function"] = "Встроенная функция"
-- en: "Custom function"
L["Custom function"] = "Пользовательская функция"
-- en: "Delete this function? Existing dependents will become unavailable."
L["Delete this function? Existing dependents will become unavailable."] = "Удалить эту функцию? Зависящий от неё код станет недоступен."
-- en: "Deletion staged. Apply to remove this function."
L["Deletion staged. Apply to remove this function."] = "Удаление подготовлено. Нажмите «Применить», чтобы удалить функцию."
